q = [QQ(_sage_const_0 )]*(NMAX+_sage_const_1 )
q[_sage_const_0 ] = QQ(-_sage_const_215040420000 )
q[_sage_const_1 ] = QQ(-_sage_const_167282265043404 )/_sage_const_905 
