for n in range(_sage_const_2 , NMAX):
    # u_{n+1} = (B_n/A_n) u_n - (C_{n-1}/A_{n-1}) u_{n-1} + (D_{n-2}/A_{n-2}) u_{n-2}
    q[n+_sage_const_1 ] = (QQ(Bcoef(n))/QQ(Acoef(n)))*q[n]            - (QQ(Ccoef(n-_sage_const_1 ))/QQ(Acoef(n-_sage_const_1 )))*q[n-_sage_const_1 ]            + (QQ(Dcoef(n-_sage_const_2 ))/QQ(Acoef(n-_sage_const_2 )))*q[n-_sage_const_2 ]
